import{_ as o,o as a,c as r,a3 as t}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Criar Novo Lembrete rápido","description":"","frontmatter":{"title":"Criar Novo Lembrete rápido","id":"eproc-lembrete-prefill","plataforma":"eproc","grupo":"Destaques e lembretes","plano":"free","desde":"1.1.2","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-lembrete-prefill"}]]},"headers":[],"relativePath":"funcionalidades/eproc-lembrete-prefill.md","filePath":"funcionalidades/eproc-lembrete-prefill.md"}'),i={name:"funcionalidades/eproc-lembrete-prefill.md"};function s(d,e,l,c,n,p){return a(),r("div",null,e[0]||(e[0]=[t('<h1 id="criar-novo-lembrete-rapido" tabindex="-1">Criar Novo Lembrete rápido <a class="header-anchor" href="#criar-novo-lembrete-rapido" aria-label="Permalink to &quot;Criar Novo Lembrete rápido&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Cria um lembrete do processo a partir de um trecho da descrição de um evento. Você seleciona o texto, clica no botão de lembrete e a tela de Novo Lembrete já abre com a descrição preenchida.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo: descrição dos eventos e balões de informação de documentos. O lembrete é criado na tela de Novo Lembrete do próprio eproc.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Selecione um trecho da descrição de um evento (ou passe o mouse sobre ele sem selecionar).</li><li>Na pequena barra que aparece ao lado, clique no botão de lembrete (&quot;Criar lembrete&quot;).</li><li>A tela de Novo Lembrete abre com a descrição preenchida, por exemplo &quot;Evento 12: prazo para manifestação&quot;.</li><li>Complete os demais campos e salve como de costume.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Oferecer botão de Novo Lembrete rápido ao passar o mouse sem selecionar texto</td><td>ligada</td><td>Desligada, o botão só aparece quando você seleciona um trecho.</td></tr><tr><td>Prefixar a descrição sugerida com &quot;Evento N: &quot;</td><td>ligada</td><td>Começa a descrição com o número do evento de onde o texto veio.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O botão de lembrete faz parte do mesmo conjunto de botões dos <a href="./eproc-destaques-trecho">Destaques de trecho</a>. Os dois recursos funcionam juntos: com qualquer um deles ligado, o botão aparece.</li><li>Se a página não tiver o link &quot;Novo Lembrete&quot;, o eploc avisa que não conseguiu abri-lo.</li></ul>',11)]))}const b=o(i,[["render",s]]);export{u as __pageData,b as default};
